package net.kasax.raft.content.food.block;

import java.util.Map;

/**
 * Shape boxes of the food models in pixels, front facing north (generated by
 * tools/content/food/gen.py from the same boxes as the block models - do not edit by hand).
 */
public final class FoodShapeData {
    private FoodShapeData() {
    }

    private static void fill0(Map<String, double[][]> map) {
        map.put("cooking_pot", new double[][]{{2.0, 0.0, 2.0, 14.0, 9.0, 14.0}});
        map.put("fish_trap", new double[][]{{1.0, 0.0, 3.0, 15.0, 11.0, 13.0}});
    }

    /** Adds every shape of this module to the map. */
    public static void fill(Map<String, double[][]> map) {
        fill0(map);
    }
}
